x = np.array([1, 2, 3, 4])
y = np.array([2, 4, 6, 8])

def predict(x, w, b):
    return w*x + b

def mse(y, yhat):
    return np.mean((y-yhat)**2)

print(mse(y, predict(x, 1, 0)))
print(mse(y, predict(x, 2, 0)))

best = None

for w in np.linspace(0, 6, 121):
    for b in np.linspace(0, 10, 121):
        yhat = w*x+b
        loss = np.mean((y-yhat)**2)

        if best is None or loss < best[0]:
            best = (loss, w, b)

print(best)

